const crypto = require('crypto');
const text = ($json.text || '').slice(0, 8000);

if (text.length < 200) return [];

const system = `You extract personal loan products from web page text.
Return ONLY JSON: {"products":[{...}]}. Rules:
- One object per distinct personal loan product. Max 5. Never invent values.
- If the page is a blog, news article or not about a specific loan offer, return {"products":[]}.
- Fields: product_name (string), interest_rate (number, lowest annual % stated, else null),
  min_income (number, monthly INR, else null), min_credit_score (integer, else null),
  max_credit_score (integer, else null), min_age (integer, else null), max_age (integer, else null),
  employment_status (array using ONLY: "salaried","self-employed","business"; null if not stated),
  criteria_text (string, the eligibility wording copied briefly, max 300 chars).
- Convert yearly income to monthly. Map "self employed professional" to "self-employed"; "business owner" or "entrepreneur" to "business".
- If a value is not clearly stated, use null.`;

return {
  json: {
    source: $json.source,
    source_url: $json.source_url,
    criteria_hash: crypto.createHash('sha256').update(text).digest('hex'),
    system,
    user: text,
  },
};

const meta = $('Prepare Prompt').item.json;
let products = [];
try {
  products = JSON.parse($json.choices[0].message.content).products || [];
} catch (e) {
  return [];
}

const ALLOWED = ['salaried', 'self-employed', 'business'];
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const int = v => num(v) === null ? null : Math.round(num(v));

const out = [];
for (const p of products) {
  const name = String(p.product_name || '').trim().slice(0, 150);
  if (!name) continue;

  const rate = num(p.interest_rate);
  if (rate !== null && (rate < 1 || rate > 50)) continue;

  const emp = Array.isArray(p.employment_status)
    ? p.employment_status.map(s => String(s).toLowerCase()).filter(s => ALLOWED.includes(s))
    : [];

  out.push({ json: {
    product_name: name,
    source: meta.source,
    source_url: meta.source_url,
    interest_rate: rate,
    min_income: num(p.min_income),
    min_credit_score: int(p.min_credit_score),
    max_credit_score: int(p.max_credit_score),
    min_age: int(p.min_age),
    max_age: int(p.max_age),
    employment_status: emp.length ? `{${emp.join(',')}}` : null,
    criteria_text: String(p.criteria_text || '').slice(0, 300),
    criteria_hash: meta.criteria_hash,
  }});
}
return out;

const domain = $('Domains').item.json.domain;
const results = $json.results || [];

return results
  .filter(r => (r.text || '').length >= 200)
  .map(r => ({
    json: { source: domain, source_url: r.url, title: r.title, text: r.text },
  }));
